individual_beta &lt;- fit_goal_hierarchical |&gt;
  spread_draws(beta[subject]) |&gt;
  median_qi(beta, .width = 0.90) |&gt;
  rename(
    beta_lower = .lower,
    beta_upper = .upper
  )

individual_goal_parameters &lt;- individual_alpha |&gt;
  select(subject, alpha, alpha_lower, alpha_upper) |&gt;
  left_join(
    individual_beta |&gt;
      select(subject, beta, beta_lower, beta_upper),
    by = "subject"
  ) |&gt;
  left_join(subject_structure, by = "subject")








