  alpha = plogis(rnorm(200, 0, 1)),
  beta = rnorm(200, 0, 0.25),
  sigma = abs(rnorm(200, 0, 0.75))
)

reference_subject &lt;- goal_data |&gt;
  filter(subject == 1)

prior_paths_goal &lt;- prior_draws_goal |&gt;
  slice_sample(n = 80) |&gt;
  mutate(
    simulation = purrr::pmap(
      list(alpha, beta, sigma),
      ~ simulate_goal_path(
        performance = reference_subject$performance,
        initial_goal = reference_subject$goal[1],
        alpha = ..1,
        beta = ..2,
        sigma = ..3
      )
    )
  ) |&gt;
  select(draw, simulation) |&gt;
  tidyr::unnest(simulation)








Figura 40.3: Traiettorie simulate prima di usare i dati per l’inferenza. Il controllo serve a valutare se i prior permettono comportamenti plausibili sulla scala degli obiettivi.




Le linee orizzontali non sono vincoli del modello: ricordano soltanto l’intervallo osservato nel compito. Se una quota eccessiva delle simulazioni producesse valori incompatibili con la scala, dovremmo restringere i prior o adottare un modello osservazionale che rispetti esplicitamente i limiti della risposta.

40.9 Implementazione in Stan
Il programma seguente condiziona sul primo obiettivo di ogni partecipante e applica la stessa coppia di parametri a tutte le traiettorie.

stan_code_goal_sample &lt;- "
data {
  int&lt;lower=1&gt; Ntotal;
  int&lt;lower=1&gt; Nsubj;
  array[Ntotal] int&lt;lower=1, upper=Nsubj&gt; subject;
  array[Ntotal] int&lt;lower=1&gt; trial;
  vector[Ntotal] goal;
  vector[Ntotal] performance;
}

parameters {
  real alpha_logit;
  real beta;
  real&lt;lower=0&gt; sigma;
}

transformed parameters {
  real&lt;lower=0, upper=1&gt; alpha = inv_logit(alpha_logit);
  vector[Ntotal] mu;

  for (i in 1:Ntotal) {
    if (trial[i] == 1) {
      mu[i] = goal[i];
    } else {
      mu[i] = mu[i - 1]
              + alpha * (performance[i - 1] - mu[i - 1])
              + beta;
    }
  }
}

model {
  alpha_logit ~ normal(0, 1);
  beta ~ normal(0, 0.25);
  sigma ~ normal(0, 0.75);

  for (i in 1:Ntotal) {
    if (trial[i] &gt; 1) {
      goal[i] ~ normal(mu[i], sigma);
    }
  }
}

generated quantities {
  vector[Ntotal] y_rep;
  vector[Ntotal] log_lik;

  for (i in 1:Ntotal) {
    if (trial[i] == 1) {
      y_rep[i] = goal[i];
      log_lik[i] = 0;
    } else {
      y_rep[i] = normal_rng(mu[i], sigma);
      log_lik[i] = normal_lpdf(goal[i] | mu[i], sigma);
    }
  }
}
"

