42.12 Controlli predittivi a posteriori
Un buon controllo deve concentrarsi su caratteristiche che il modello intende spiegare.

replicated_statistics &lt;- function(
    fit,
    rich_is_A,
    n_replications = 300
) {
  choice_matrix &lt;- fit$draws(
    "choice_rep",
    format = "draws_matrix"
  ) |&gt;
    as.matrix()

  reward_matrix &lt;- fit$draws(
    "reward_rep",
    format = "draws_matrix"
  ) |&gt;
    as.matrix()

  selected &lt;- sample(
    seq_len(nrow(choice_matrix)),
    size = min(n_replications, nrow(choice_matrix))
  )

  purrr::map_dfr(
    selected,
    ~ behavioral_statistics(
      choice = as.integer(choice_matrix[.x, ]),
      reward = as.integer(reward_matrix[.x, ]),
      rich_is_A = rich_is_A
    ),
    .id = "replication"
  )
}

rw_rep_stats &lt;- replicated_statistics(
  fit = fit_rw,
  rich_is_A = sim_rw$rich_is_A
)

rw_observed_stats &lt;- behavioral_statistics(
  choice = sim_rw$choice,
  reward = sim_rw$reward,
  rich_is_A = sim_rw$rich_is_A
)








